let seed, pal, FG, BG, S, maxLen, spheres;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	describe("sphere packing");
	// drawingContext.globalCompositeOperation = "destination-over";
	frameRate(30);
	stroke(240); noStroke();
	S = ~~max(width, height);
	maxLen = S/3;

	pal = [...random(palettes)];
	FG = random(pal);
	BG = adjColorBrightness(adjColorSaturation(FG, 1.5), 0.5);
	FG = adjColorBrightness(adjColorSaturation(FG, 0.75), 0.75);

	seed = ~~random(987654321);
	noiseSeed(seed);

	spheres = [];
	tryAddSpheres(100);
	// console.log(spheres);
}

function draw() {
	tryAddSpheres(100);
	background(BG);
	orbitControl();
	lights();
	pointLight(255, 255, 255, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2, 250);
	specularMaterial(255);
	shininess(75);

	const yPlane = -(frameCount % height) + height/2;
	push();
		stroke(FG); noFill(); sphere(maxLen);
		// stroke(128, 128); line(-width/2, yy, width, yy);
		translate(0, yPlane, 0);
		rotateX(HALF_PI);
		// noStroke(); fill("rgba(128,128,128,0.2)"); plane(S);
		stroke("rgba(128,128,128,0.8)"); for (let sze = S; sze > 1; sze -= S/10) plane(sze);
	pop();

	for (let s of spheres) {
		if (s.pos.y - s.sze/2 < yPlane) continue;
		push();
		translate(s.pos);
		fill(s.clr)
		sphere(s.sze);
		pop();
	}
}

function tryAddSpheres(num = 1) {
	for (let i = 0; i < num; i++) {
		const sze = random(S/100, S/3);
		const len = random(maxLen-sze);
		const pos = p5.Vector.random3D().mult(len);
		const clr = random(pal);
		const newSphere = {pos, sze, clr};
		// space filling collision detection
		let notCollides = true;
		for (let s of spheres) {
			if (dist(s.pos.x, s.pos.y, s.pos.z, newSphere.pos.x, newSphere.pos.y, newSphere.pos.z) < (s.sze + newSphere.sze)) {
			// if (p5.Vector.magSq(s.pos, newSphere) < pow(s.sze + newSphere.sze, 2)) {
				notCollides = false;
				break;
			}
		}
		if (notCollides) {
			spheres.push(newSphere);
		}
	}
}

function doubleClicked() {
	if (mouseButton !== RIGHT) setup();
